def main():
    assert sorted(P.keys()) == sorted(EXPECTED), (sorted(P.keys()), EXPECTED)
    assert len(P) == 20, len(P)
    OUT.mkdir(parents=True, exist_ok=True)
    total = 0
    tc = {'changed_main': 0, 'reserve_used': 0, 'disputed': 0}
    for cid in EXPECTED:
        rec = P[cid]
        obj = {'case_id': cid,
               'prediction_text': rec['prediction_text'],
               'basis': rec['basis'],
               'confidence': rec['confidence'],
               'trigger': rec['trigger']}
        for k in tc:
            if obj['trigger'][k]:
                tc[k] += 1
        path = OUT / (cid + '.json')
        path.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding='utf-8')
    # verify: open each expected file precisely by id (no listing/glob over predictions)
    written = 0
    for cid in EXPECTED:
        path = OUT / (cid + '.json')
        data = json.loads(path.read_text(encoding='utf-8'))
        assert data['case_id'] == cid, cid
        assert set(data.keys()) == {'case_id','prediction_text','basis','confidence','trigger'}, cid
        assert isinstance(data['confidence'], float) and 0.0 <= data['confidence'] <= 1.0, cid
        assert set(data['trigger'].keys()) == {'changed_main','reserve_used','disputed','reason'}, cid
        written += 1
        total += path.stat().st_size
    print('batch_cases=', len(EXPECTED))
    print('written=', written)
    print('trigger_counts=', tc)
    print('total_bytes=', total)

if __name__ == '__main__':
    main()
